CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,name TEXT NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'student' CHECK(role IN ('student','admin')),created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_user ON sessions(user_id);
CREATE TABLE IF NOT EXISTS study_sets(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,title TEXT NOT NULL,notes TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS sets_user ON study_sets(user_id);
CREATE TABLE IF NOT EXISTS documents(id TEXT PRIMARY KEY,set_id TEXT NOT NULL UNIQUE REFERENCES study_sets(id) ON DELETE CASCADE,filename TEXT NOT NULL,bytes INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS questions(id TEXT PRIMARY KEY,set_id TEXT NOT NULL REFERENCES study_sets(id) ON DELETE CASCADE,position INTEGER NOT NULL,question TEXT NOT NULL,choices TEXT NOT NULL,answer INTEGER NOT NULL CHECK(answer BETWEEN 0 AND 3),explanation TEXT NOT NULL,difficulty TEXT NOT NULL,topic TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS questions_set ON questions(set_id);
CREATE TABLE IF NOT EXISTS flashcards(id TEXT PRIMARY KEY,set_id TEXT NOT NULL REFERENCES study_sets(id) ON DELETE CASCADE,front TEXT NOT NULL,back TEXT NOT NULL,topic TEXT NOT NULL,difficulty TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS flashcard_reviews(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,card_id TEXT NOT NULL REFERENCES flashcards(id) ON DELETE CASCADE,known INTEGER NOT NULL,reviewed_at INTEGER NOT NULL,due_at INTEGER NOT NULL,interval_days INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS reviews_user ON flashcard_reviews(user_id,card_id,reviewed_at);
CREATE TABLE IF NOT EXISTS quiz_attempts(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,set_id TEXT NOT NULL REFERENCES study_sets(id) ON DELETE CASCADE,score INTEGER NOT NULL,total INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS quiz_answers(attempt_id TEXT NOT NULL REFERENCES quiz_attempts(id) ON DELETE CASCADE,question_id TEXT NOT NULL REFERENCES questions(id) ON DELETE CASCADE,answer INTEGER NOT NULL,PRIMARY KEY(attempt_id,question_id));
CREATE TABLE IF NOT EXISTS subscriptions(user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,starts_at INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS generation_usage(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,day TEXT NOT NULL,status TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS usage_day ON generation_usage(user_id,day);
CREATE TABLE IF NOT EXISTS sync_changes(seq INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,set_id TEXT NOT NULL,version INTEGER NOT NULL,deleted INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS sync_user ON sync_changes(user_id,seq);
CREATE TABLE IF NOT EXISTS admin_audit_logs(id TEXT PRIMARY KEY,admin_id TEXT REFERENCES users(id) ON DELETE SET NULL,target_id TEXT,action TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS application_errors(id TEXT PRIMARY KEY,code TEXT NOT NULL,created_at INTEGER NOT NULL);
